//! JSON Schemas for the scenario input and the run outputs.
//!
//! The schemas describe the serialized shapes of [`Scenario`], [`SigintRun`]
//! and [`CuasRun`]. Copies generated by the CLI (`spectra-sim schema ...`) are
//! committed under `schemas/` and checked by `tests/schema_contracts.rs`.

use serde_json::Value;

use crate::{CuasRun, Scenario, SigintRun};

fn schema_value<T: schemars::JsonSchema>() -> Value {
    let schema = schemars::schema_for!(T);
    // A schemars RootSchema is plain data and always serializes; the fallback
    // only exists to keep this function infallible without `unwrap`.
    serde_json::to_value(schema).unwrap_or(Value::Null)
}

/// JSON Schema of a scenario file ([`Scenario`]).
pub fn scenario_schema() -> Value {
    schema_value::<Scenario>()
}

/// JSON Schema of the result of a SIGINT run ([`SigintRun`]).
pub fn sigint_run_schema() -> Value {
    schema_value::<SigintRun>()
}

/// JSON Schema of the result of a counter-UAS run ([`CuasRun`]).
pub fn cuas_run_schema() -> Value {
    schema_value::<CuasRun>()
}
